/* BRAVE 365 / production-like demo layer: persistent local state, calculators, notifications and resilient UI states. */
const DEMO_DB_KEY='brave365_catalog_demo_v1';
const demoDB=JSON.parse(localStorage.getItem(DEMO_DB_KEY)||'{}');
const persistDemo=()=>localStorage.setItem(DEMO_DB_KEY,JSON.stringify(demoDB));
const currentProject=()=>Number(location.hash.match(/^#site-(\d+)/)?.[1]||0);
const projectTools={
  1:['Ипотечный калькулятор','Стоимость квартиры','Срок, лет','Ставка, %'],
  2:['Запись к врачу','Специализация','Дата визита','Время'],
  3:['Расчёт платежа','Стоимость автомобиля','Первоначальный взнос','Срок, лет'],
  4:['Расчёт проекта','Площадь, м²','Уровень отделки','Срок, месяцев'],
  5:['Корзина','Выберите размер','Количество','Промокод'],
  6:['Оценка разработки','Тип продукта','Срок, месяцев','Команда'],
  7:['Подбор тура','Бюджет, ₽','Дата вылета','Длительность'],
  8:['Доходность — демо','Сумма, ₽','Срок, лет','Стратегия'],
  9:['Запись на занятие','Направление','Дата','Тренер'],
  10:['Запрос консультации','Направление права','Срочность','Формат связи']
};
function dbFor(id){if(!demoDB[id])demoDB[id]={favorites:[],compare:[],cart:[],requests:[],notifications:[]};return demoDB[id]}
function layerToast(message){window.showToast?.(message);if(!window.showToast){const x=document.createElement('div');x.className='toast';x.textContent=message;document.body.append(x);setTimeout(()=>x.remove(),2600)}}
function modal(title,body){document.querySelector('.demo-modal')?.remove();const m=document.createElement('div');m.className='demo-modal';m.innerHTML=`<div class="demo-modal-card"><button class="demo-modal-close" aria-label="Закрыть">×</button><div class="demo-kicker">BRAVE 365 / DEMO</div><h3>${title}</h3><div>${body}</div></div>`;document.body.append(m);m.querySelector('.demo-modal-close').onclick=()=>m.remove();m.onclick=e=>{if(e.target===m)m.remove()}}
function calcValue(id,values){const n=v=>Number(String(v||'').replace(/\s/g,'').replace(',','.'))||0;if(id===1){const price=n(values[0]),years=n(values[1])||20,rate=n(values[2])||8;const monthly=price*(rate/1200)/(1-Math.pow(1+rate/1200,-years*12));return monthly?`${Math.round(monthly).toLocaleString('ru-RU')} ₽ / месяц`:'Введите стоимость'}if(id===3){const price=n(values[0]),down=n(values[1]),years=n(values[2])||5;const pay=(price-down)/(years*12);return pay?`${Math.round(pay).toLocaleString('ru-RU')} ₽ / месяц`:'Введите данные'}if(id===4){const area=n(values[0]),months=n(values[2])||8;return area?`от ${Math.round(area*85000).toLocaleString('ru-RU')} ₽ · ${months} мес.`:'Введите площадь'}if(id===7){return n(values[0])?`Подобрано 12 вариантов до ${n(values[0]).toLocaleString('ru-RU')} ₽`:'Введите бюджет'}if(id===8){const sum=n(values[0]),years=n(values[1])||5;return sum?`Демо-результат: ${Math.round(sum*Math.pow(1.08,years)).toLocaleString('ru-RU')} ₽`:'Введите сумму'}if(id===6){return 'Ориентир подготовлен по демо-параметрам'}return 'Сценарий готов к подтверждению'}
function toolHtml(id){const t=projectTools[id];if(!t)return '';const fields=t.slice(1).map((label,i)=>`<label>${label}<input data-tool-field="${i}" placeholder="${i===0?'Введите значение':'Выберите вариант'}" ${id===2||id===9?'type="text"':''}></label>`).join('');return `<section class="demo-section production-toolkit"><div class="demo-section-title"><h3>${t[0]}</h3><p>Функция работает в демо-режиме. Данные сохраняются только на этом устройстве.</p></div><div class="tool-grid"><div class="demo-form demo-tool-form">${fields}<button class="demo-primary" data-tool-submit>Рассчитать / подтвердить ↗</button><div class="demo-form-message" data-tool-result></div></div><div class="tool-state"><div class="tool-state-label">Состояние сценария</div><strong data-tool-state>Ожидание ввода</strong><span>Loading, success и error-состояния предусмотрены.</span><div class="state-dots"><i></i><i></i><i></i></div></div></div></section>`}
function addProductionLayer(){const id=currentProject();if(!id||!document.querySelector('.demo-app'))return;const body=document.querySelector('.demo-body');if(!body||body.querySelector('.production-toolkit'))return;body.insertAdjacentHTML('beforeend',toolHtml(id));const app=document.querySelector('.demo-app');const top=document.querySelector('.demo-top-actions');if(top&&!top.querySelector('[data-open-new]')){const b=document.createElement('button');b.className='demo-icon-btn';b.dataset.openNew='1';b.textContent='Новая вкладка';b.onclick=()=>window.open(location.href,'_blank','noopener');top.insertBefore(b,top.firstChild)}document.querySelectorAll('[data-tool-submit]').forEach(btn=>btn.onclick=()=>{const form=btn.closest('.demo-tool-form'),fields=[...form.querySelectorAll('[data-tool-field]')].map(x=>x.value),state=form.querySelector('[data-tool-state]'),result=form.querySelector('[data-tool-result]');if(fields.some(x=>!x.trim())){state.textContent='Ошибка: заполните поля';state.dataset.state='error';result.textContent='Нужно заполнить все поля.';return}state.textContent='Готово';state.dataset.state='success';result.textContent=calcValue(id,fields);dbFor(id).notifications.push({message:'Сценарий выполнен',at:Date.now()});persistDemo();layerToast('Результат сохранён в демо-сценарии')});const login=document.querySelector('.js-login');if(login&&!login.querySelector('[data-auth-extra]')){const e=document.createElement('div');e.dataset.authExtra='1';e.className='auth-extra';e.innerHTML='<button type="button" data-register>Создать демо-аккаунт</button><button type="button" data-recover>Восстановить пароль</button>';login.append(e);e.querySelector('[data-register]').onclick=()=>{localStorage.demoUser='demo@example.com';layerToast('Демо-аккаунт создан');go(id,'кабинет')};e.querySelector('[data-recover]').onclick=()=>modal('Восстановление доступа','Ссылка для восстановления отправлена в демо-режиме.')}}
const observer=new MutationObserver(()=>addProductionLayer());observer.observe(document.body,{childList:true,subtree:true});window.addEventListener('hashchange',()=>setTimeout(addProductionLayer,50));setTimeout(addProductionLayer,120);

